#include "model_body_selection_candidate.h"
#include <iostream>
int main(){try{size_t cases=0;for(uint32_t body=0;body<60;++body){auto result=modelBodySelectionCandidate(body,{2,3,5},{1,2,6});std::vector<uint32_t> expected={body%2,(body%6)/2,(body/6)%5};if(result!=expected)throw std::runtime_error("mixed radix selection mismatch");++cases;}if(modelBodySelectionCandidate(2147483647,{1,1,1},{1,1,1})!=std::vector<uint32_t>({0,0,0}))throw std::runtime_error("single model group mismatch");bool rejected=false;try{modelBodySelectionCandidate(0,{2},{0});}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("zero base accepted");std::cout<<"body selection passed mixed_radix_cases="<<cases<<" single_model_groups=3 zero_base_rejected=1 native_SFM_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
